  "{count} entries were written by a clinic": { zero: "لا سجلات كتبتها عيادة", one: "سجل واحد كتبته عيادة", two: "سجلان كتبتهما عيادة", few: "{count} سجلات كتبتها عيادة", many: "{count} سجلًا كتبتها عيادة", other: "{count} سجل كتبتها عيادة" },
  "All {count} entries were added by the owner and have not been confirmed by a clinic. Ask to see the original paperwork before you commit.": { zero: "لا توجد سجلات.", one: "السجل الوحيد أضافه المالك ولم تؤكده عيادة. اطلب رؤية الأوراق الأصلية قبل أن تلتزم.", two: "السجلان أضافهما المالك ولم تؤكدهما عيادة. اطلب رؤية الأوراق الأصلية قبل أن تلتزم.", few: "كل السجلات الـ{count} أضافها المالك ولم تؤكدها عيادة. اطلب رؤية الأوراق الأصلية قبل أن تلتزم.", many: "كل السجلات الـ{count} أضافها المالك ولم تؤكدها عيادة. اطلب رؤية الأوراق الأصلية قبل أن تلتزم.", other: "كل السجلات الـ{count} أضافها المالك ولم تؤكدها عيادة. اطلب رؤية الأوراق الأصلية قبل أن تلتزم." },
